<template><div v-if="b" class="rounded bg-white p-8 shadow"><h1 class="text-3xl font-bold">{{b.title}}</h1><p class="mt-2 text-sm text-slate-500">{{b.writerName}} · 조회 {{b.viewCount}}</p><article class="my-10 whitespace-pre-wrap">{{b.content}}</article><div class="flex gap-2"><RouterLink v-if="canEdit" :to="`/boards/${b.id}/edit`" class="rounded bg-slate-900 px-4 py-2 text-white">수정</RouterLink><button v-if="canEdit" @click="remove" class="rounded border px-4 py-2">삭제</button><RouterLink to="/boards" class="rounded border px-4 py-2">목록</RouterLink></div></div></template>
<script setup>import{computed,onMounted,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{useAuthStore}from'../stores/auth';import{boardApi}from'../api/boardApi';const route=useRoute(),router=useRouter(),auth=useAuthStore(),b=ref(null);const canEdit=computed(()=>auth.isAdmin||b.value?.userid===auth.member?.userid);onMounted(async()=>b.value=(await boardApi.get(route.params.id)).data);async function remove(){if(confirm('삭제할까요?')){await boardApi.remove(route.params.id);router.push('/boards')}}</script>